247	    /**
248	     * Maximum number of owners allowed in a single city. Creating an owner in a city that has
249	     * already reached this many owners is rejected as a conflict.
250	     */
251	    static final int MAX_OWNERS_PER_CITY = 50;
252	
253	    /**
254	     * Maximum number of owners allowed to register on a single day. Creating an owner once a day has
255	     * already reached this many registrations is rejected as a rate-limit violation.
256	     */
257	    static final int MAX_OWNERS_PER_DAY = 100;
258	
259	    /**
260	     * Number of owners that must already have registered on a day before a new registration is
261	     * flagged with a bulk-signup warning. Once the count already recorded for the day exceeds this
262	     * value, the new owner carries {@code bulkSignupWarning == true}.
263	     */
264	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
265	
266	    @Override
267	    @Transactional
268	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
269	        if (DisposableEmailDomains.isDisposable(owner.getEmail())) {
270	            throw new DisposableEmailDomainException(owner.getEmail());
271	        }
272	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
273	        rejectIdentityCollision(owner);
274	        List<Owner> householdMembers = findHouseholdMembers(owner);
275	        if (!householdMembers.isEmpty() && !sharesHousehold) {
276	            throw new HouseholdDuplicateException(owner.getHouseholdId());
277	        }
278	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
279	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
280	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
281	        }
282	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
283	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
284	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
285	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
286	            throw new DailyOwnerLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
287	        }
288	        owner.setBulkSignupWarning(ownersOnDate > BULK_SIGNUP_WARNING_THRESHOLD);
289	        flagPossibleDuplicate(owner, householdMembers, sharesHousehold);
290	        owner.setNamesakeCount(countNamesakes(owner));
291	        owner.setHouseholdSize(householdMembers.size() + 1);
292	        owner.setMembershipLevel(OwnerMembership.cappedLevel(owner, householdMembers));
293	        owner.setCustomerCode(assignCustomerCode(owner));
294	        ownerRepository.save(owner);
295	        ownerAuditLogger.ownerCreated(owner);
296	        return owner.getHouseholdId();
297	    }
298	
299	    /**
300	     * Reject creating an owner whose whole {@link OwnerIdentityKey identity key} already belongs to
301	     * another owner. Because the telephone is part of the key, only an existing owner sharing every
302	     * key component (normalized telephone, email and household identifier) is a duplicate.
303	     */
304	    private void rejectIdentityCollision(Owner owner) {
305	        String identityKey = OwnerIdentityKey.of(owner);
306	        boolean collides = ownerRepository.findByTelephone(owner.getTelephone()).stream()
307	            .filter(ClinicServiceImpl::isActive)
308	            .anyMatch(existing -> identityKey.equals(OwnerIdentityKey.of(existing)));
309	        if (collides) {
310	            throw new DuplicateOwnerException(identityKey);
311	        }
312	    }
313	
314	    /**
315	     * Whether an existing owner is still active, i.e. has not been soft-deleted. Soft-deleted owners
316	     * are retained for history but ignored by the create-time duplicate and identity checks.
317	     */
318	    private static boolean isActive(Owner owner) {
319	        return !Boolean.TRUE.equals(owner.getDeleted());
320	    }
321	
322	    /**
323	     * Build the new owner's {@code customerCode} and de-duplicate it against existing owners. The
324	     * base code is derived from the owner's locality, telephone and last name; if it already belongs
325	     * to another owner it is suffixed with the smallest {@code "-<n>"} (n &gt;= 2) that is still free.
326	     */
327	    private String assignCustomerCode(Owner owner) {
328	        String baseCode = CustomerCodeGenerator.format(
329	            LocalityResolver.resolve(owner.getCity(), owner.getPostcode()),
330	            owner.getTelephone(), owner.getLastName());
331	        Set<String> takenCodes = ownerRepository.findByCustomerCodeStartingWith(baseCode).stream()
332	            .map(Owner::getCustomerCode)
333	            .collect(Collectors.toSet());
334	        return CustomerCodeGenerator.deduplicate(baseCode, takenCodes::contains);
335	    }
336	
337	    /**
338	     * Flag the new owner as a possible (soft) duplicate of an existing household member carrying a
339	     * different telephone. The new owner is still created; {@code possibleDuplicate} is set to
340	     * whether such a match exists and {@code possibleDuplicateOf} to the matching owner's id (the
341	     * lowest when several match), or {@code null} when there is no match.
342	     *
343	     * <p>An owner that explicitly declares {@code sharesHousehold} is a <em>declared</em> household
344	     * member rather than a suspected duplicate, so it is never flagged.
345	     */
346	    private void flagPossibleDuplicate(Owner owner, List<Owner> householdMembers, boolean sharesHousehold) {
347	        Owner match = sharesHousehold ? null : householdMembers.stream()
348	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
349	            .min(Comparator.comparingInt(Owner::getId))
350	            .orElse(null);
351	        owner.setPossibleDuplicate(match != null);
352	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
353	    }
354	
355	    @Override
356	    @Transactional
357	    public void saveOwner(Owner owner) throws DataAccessException {
358	        ownerRepository.save(owner);
359	    }
360	
361	    /**
362	     * Count the owners that already exist sharing this owner's first name and last name, compared
363	     * case-insensitively. Invoked before the new owner is persisted, so it never counts itself.
364	     */
365	    private int countNamesakes(Owner owner) {
366	        return (int) ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
367	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName()))
368	            .count();
369	    }
370	
371	    /**
372	     * Find the existing owners that already share this owner's household, i.e. that derive the same
373	     * computed {@code householdId} (the same last name and postcode). An owner without a postcode
374	     * has no household peers.
375	     */
376	    private List<Owner> findHouseholdMembers(Owner owner) {
377	        if (owner.getPostcode() == null) {
378	            return List.of();
379	        }
380	        String householdId = owner.getHouseholdId();
381	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
382	            .filter(ClinicServiceImpl::isActive)
383	            .filter(existing -> householdId.equals(
384	                HouseholdIdGenerator.generate(existing.getLastName(), existing.getPostcode())))
385	            .toList();
386	    }
387	
388	    @Override
