406	    private <T> T findEntityById(Supplier<T> supplier) {
407	        try {
408	            return supplier.get();
409	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
410	            // Just ignore not found exceptions for Jdbc/Jpa realization
411	            return null;
412	        }
413	    }
414	
