17	package org.springframework.samples.petclinic.util;
18	
19	import java.util.Locale;
20	import java.util.regex.Pattern;
21	
22	/**
23	 * Reduces free-text values to a canonical form for case- and whitespace-insensitive
24	 * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace are
25	 * collapsed to a single space, and the result is lower-cased. Two values that differ only
26	 * in letter casing or in how their whitespace is laid out normalize to the same string.
27	 */
28	public final class TextNormalizer {
29	
30	    /** Any run of whitespace, collapsed to a single space. */
31	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
32	
33	    private TextNormalizer() {
34	    }
35	
36	    /**
37	     * Normalize the given value for comparison.
38	     *
39	     * @param value the raw value (may be {@code null})
40	     * @return the trimmed, whitespace-collapsed, lower-cased value, or {@code null} when
41	     * {@code value} is {@code null}
42	     */
43	    public static String normalize(String value) {
44	        if (value == null) {
45	            return null;
46	        }
47	        return WHITESPACE.matcher(value.strip()).replaceAll(" ").toLowerCase(Locale.ROOT);
48	    }
49	}
