21		@Test
22		void coreRejectsDuplicateIdentity() throws Exception {
23			ObjectNode a = structuredOwner();
24			a.put("email", uniqueEmail());
25			createOwnerOk(a);
26			ObjectNode b = a.deepCopy(); // identical telephone / email / lastName -> same v2 key
27			createOwner(b).andExpect(status().isConflict());
28		}
29	}
